import { describe, it, expect, vi, beforeEach } from 'vitest';
import { ProviderCredentialLinkService } from './provider-credential-link.service';

function makeService() {
  const mediaRepository = {
    upsert: vi.fn().mockResolvedValue({}),
    getByIdentifier: vi.fn().mockResolvedValue(null),
    // 1.2: the sync path reads the target row version-agnostically. Delegate to
    // getByIdentifier so per-test mocks drive both.
    findAnyByIdentifier: vi.fn((orgId: string, id: string) =>
      mediaRepository.getByIdentifier(orgId, id),
    ),
  };
  const aiRepository = {
    upsert: vi.fn().mockResolvedValue({}),
    getByIdentifier: vi.fn().mockResolvedValue(null),
    findAnyByIdentifier: vi.fn((orgId: string, id: string) =>
      aiRepository.getByIdentifier(orgId, id),
    ),
  };
  const encryption = { encrypt: vi.fn((v: string) => `enc(${v})`) };
  const resolution = { latestActiveVersion: vi.fn().mockReturnValue('v1') };
  const service = new ProviderCredentialLinkService(
    mediaRepository as never,
    aiRepository as never,
    encryption as never,
    resolution as never,
  );
  return { service, mediaRepository, aiRepository, encryption, resolution };
}

describe('ProviderCredentialLinkService (§11.4 auto-config live-link)', () => {
  beforeEach(() => vi.clearAllMocks());

  it('marks only openai and minimax as linked', () => {
    const { service } = makeService();
    expect(service.isLinked('openai')).toBe(true);
    expect(service.isLinked('minimax')).toBe(true);
    expect(service.isLinked('anthropic')).toBe(false);
    expect(service.isLinked('luma')).toBe(false);
  });

  it('mirrors AI credentials onto the media config (encrypted) for linked providers', async () => {
    const { service, mediaRepository } = makeService();
    await service.syncFromAiProvider('org-1', 'openai', { apiKey: 'sk-123' });

    expect(mediaRepository.upsert).toHaveBeenCalledWith(
      'org-1',
      'openai',
      {
        enabled: true,
        credentials: `enc(${JSON.stringify({ apiKey: 'sk-123' })})`,
      },
      'v1',
    );
  });

  it('pins the mirror-target row version instead of hardcoding v1 (1.4)', async () => {
    const { service, mediaRepository, resolution } = makeService();
    // existing media row is pinned to v2 → the mirror write must target v2.
    mediaRepository.getByIdentifier.mockResolvedValue({ identifier: 'openai', version: 'v2', enabled: true });

    await service.syncFromAiProvider('org-1', 'openai', { apiKey: 'sk-123' });

    expect(mediaRepository.upsert).toHaveBeenCalledWith(
      'org-1',
      'openai',
      expect.objectContaining({ enabled: true }),
      'v2',
    );
    expect(resolution.latestActiveVersion).not.toHaveBeenCalled();
  });

  // 1.1(c): a re-key must NOT silently re-enable a deliberately-disabled mirror row.
  it('preserves a disabled mirror row\'s enabled flag on re-key (1.1c)', async () => {
    const { service, mediaRepository } = makeService();
    mediaRepository.getByIdentifier.mockResolvedValue({ identifier: 'openai', version: 'v1', enabled: false });

    await service.syncFromAiProvider('org-1', 'openai', { apiKey: 'sk-new' });

    expect(mediaRepository.upsert).toHaveBeenCalledWith(
      'org-1',
      'openai',
      expect.objectContaining({ enabled: false }),
      'v1',
    );
  });

  it('does not touch the media row\'s storage binding (only credentials/enabled)', async () => {
    const { service, mediaRepository } = makeService();
    await service.syncFromAiProvider('org-1', 'minimax', { apiKey: 'mm-key' });
    const data = mediaRepository.upsert.mock.calls[0][2];
    expect(Object.keys(data).sort()).toEqual(['credentials', 'enabled']);
  });

  it('mirrors media credentials onto the AI config (encrypted) for linked providers', async () => {
    const { service, aiRepository } = makeService();
    await service.syncFromMediaProvider('org-1', 'minimax', { apiKey: 'mm-key' });

    expect(aiRepository.upsert).toHaveBeenCalledWith(
      'org-1',
      'minimax',
      {
        enabled: true,
        credentials: `enc(${JSON.stringify({ apiKey: 'mm-key' })})`,
      },
      'v1',
    );
  });

  it('ignores non-linked providers in both directions', async () => {
    const { service, mediaRepository, aiRepository } = makeService();
    await service.syncFromAiProvider('org-1', 'anthropic', { apiKey: 'x' });
    await service.syncFromMediaProvider('org-1', 'heygen', { apiKey: 'x' });
    expect(mediaRepository.upsert).not.toHaveBeenCalled();
    expect(aiRepository.upsert).not.toHaveBeenCalled();
  });

  it('is non-fatal when the mirror write fails', async () => {
    const { service, mediaRepository, aiRepository } = makeService();
    mediaRepository.upsert.mockRejectedValue(new Error('db down'));
    aiRepository.upsert.mockRejectedValue(new Error('db down'));

    await expect(service.syncFromAiProvider('org-1', 'openai', { apiKey: 'k' })).resolves.toBeUndefined();
    await expect(service.syncFromMediaProvider('org-1', 'openai', { apiKey: 'k' })).resolves.toBeUndefined();
  });
});

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';

const mockSafeFetch = vi.fn();
vi.mock('@postmill-ai/nestjs-libraries/dtos/webhooks/safe.fetch', () => ({
  safeFetch: (url: string, init?: RequestInit) => mockSafeFetch(url, init),
}));

// The outro fade is unit-tested in audio-outro-fade.spec.ts; here it is mocked
// (identity by default) so these specs pin only the WIRING: which operations
// get faded, and that a fade failure never loses the artifact.
const mockApplyAudioOutroFade = vi.fn((buffer: Buffer) => Promise.resolve(buffer));
vi.mock('@postmill-ai/nestjs-libraries/media/audio-outro-fade', () => ({
  applyAudioOutroFade: (buffer: Buffer, mime: string, durationSeconds?: number) =>
    mockApplyAudioOutroFade(buffer, mime, durationSeconds),
}));

import { MediaJobLifecycleService } from './media-job-lifecycle.service';
import { AIMediaJob } from '@prisma/client';

const tinyJpeg = Buffer.from([
  0xff, 0xd8, 0xff, 0xe0, 0x00, 0x10, 0x4a, 0x46,
  0x49, 0x46, 0x00, 0x01, 0x01, 0x01, 0x00, 0x48,
]);
const tinyMp4 = Buffer.from([
  0x00, 0x00, 0x00, 0x18, 0x66, 0x74, 0x79, 0x70,
  0x69, 0x73, 0x6f, 0x6d, 0x00, 0x00, 0x02, 0x00,
  0x69, 0x73, 0x6f, 0x6d, 0x69, 0x73, 0x6f, 0x32,
  0x6d, 0x70, 0x34, 0x31,
]);

function makeJob(overrides: Partial<AIMediaJob> = {}): AIMediaJob {
  return {
    id: 'job-1',
    organizationId: 'org-1',
    userId: 'user-1',
    provider: 'luma',
    operation: 'video',
    status: 'pending',
    artifactUrl: 'pending://luma-ext-1',
    provenance: null,
    costUsd: 0.5,
    creditType: 'ai_videos',
    error: null,
    createdAt: new Date(),
    updatedAt: new Date(),
    ...overrides,
  } as AIMediaJob;
}

function makeService() {
  const jobs = new Map<string, AIMediaJob>();
  const aiSettings = {
    createMediaJob: vi.fn().mockImplementation(async (data: Record<string, unknown>) => {
      const job = makeJob({ ...(data as Partial<AIMediaJob>), id: 'created-1', artifactUrl: null });
      jobs.set(job.id, job);
      return job;
    }),
    updateMediaJob: vi.fn().mockImplementation(async (_orgId: string, id: string, data: Partial<AIMediaJob>) => {
      const job = { ...(jobs.get(id) || makeJob({ id })), ...data };
      jobs.set(id, job as AIMediaJob);
      return job;
    }),
    getMediaJobById: vi.fn().mockImplementation(async (_orgId: string, id: string) => jobs.get(id) || null),
    getMediaJobByIdUnscoped: vi.fn().mockImplementation(async (id: string) => jobs.get(id) || null),
    getPendingMediaJobs: vi.fn().mockResolvedValue([]),
    // §3.1: atomic CAS on status. Mutates the shared job object synchronously (no await
    // between read and write) so it faithfully models the DB's conditional updateMany —
    // exactly one of two concurrent claimants sees the row still in `from`.
    claimMediaJobStatus: vi.fn().mockImplementation(async (_orgId: string, id: string, from: string[], to: string) => {
      const job = jobs.get(id);
      if (!job || !from.includes(job.status)) return 0;
      job.status = to as AIMediaJob['status'];
      jobs.set(id, job);
      return 1;
    }),
    // §3.1 crash-recovery: default no-op (no stranded rows) for the sweep pre-pass.
    reclaimStaleLandingJobs: vi.fn().mockResolvedValue(0),
  };

  const pollJob = vi.fn();
  const adapter = { identifier: 'luma', pollJob };
  const resolution = { resolveMedia: vi.fn().mockReturnValue(adapter) };

  const orgSettings = {
    getConfigForProvider: vi.fn().mockResolvedValue({
      credentials: { apiKey: 'luma-key' },
      storageProviderId: null,
      storageRootFolderId: null,
      version: 'v1',
    }),
    getStandardFolderId: vi.fn().mockResolvedValue('folder-video-1'),
  };

  const storageAdapter = { writeBuffer: vi.fn().mockResolvedValue('/uploads/org-1/artifact.mp4') };
  const storageService = {
    getAdapter: vi.fn().mockResolvedValue(storageAdapter),
    getLocalAdapterForOrg: vi.fn().mockResolvedValue(storageAdapter),
  };

  const mediaRepository = {
    saveGeneratedMedia: vi.fn().mockResolvedValue({ id: 'media-1', path: '/uploads/org-1/artifact.mp4' }),
    // 1.3 (orchestrator): _writeToTenantStorage validates a client folderId's ownership;
    // null = not owned → fall through to standard folder resolution (default behaviour).
    resolveOwnedFolderId: vi.fn().mockResolvedValue(null),
  };

  const notificationService = { notify: vi.fn().mockResolvedValue(undefined) };

  const videoThumbnailService = { enqueueGenerate: vi.fn() };

  const service = new MediaJobLifecycleService(
    aiSettings as never,
    orgSettings as never,
    resolution as never,
    storageService as never,
    mediaRepository as never,
    notificationService as never,
    videoThumbnailService as never,
  );

  return {
    service,
    jobs,
    aiSettings,
    pollJob,
    resolution,
    orgSettings,
    storageAdapter,
    storageService,
    mediaRepository,
    notificationService,
    videoThumbnailService,
  };
}

describe('MediaJobLifecycleService (§11.2 async job lifecycle)', () => {
  const originalBackendUrl = process.env.NEXT_PUBLIC_BACKEND_URL;
  const originalJwt = process.env.JWT_SECRET;

  beforeEach(() => {
    vi.clearAllMocks();
    mockSafeFetch.mockReset();
    process.env.JWT_SECRET = 'test-secret';
    process.env.NEXT_PUBLIC_BACKEND_URL = 'https://api.example.com';
  });

  afterEach(() => {
    if (originalBackendUrl === undefined) delete process.env.NEXT_PUBLIC_BACKEND_URL;
    else process.env.NEXT_PUBLIC_BACKEND_URL = originalBackendUrl;
    if (originalJwt === undefined) delete process.env.JWT_SECRET;
    else process.env.JWT_SECRET = originalJwt;
  });

  describe('job creation + provider reference', () => {
    it('creates a pending AIMediaJob row', async () => {
      const { service, aiSettings } = makeService();
      const job = await service.createPendingJob({
        organizationId: 'org-1',
        userId: 'user-1',
        provider: 'luma',
        operation: 'video',
        costUsd: 0.5,
        creditType: 'ai_videos',
      });
      expect(job.id).toBe('created-1');
      expect(aiSettings.createMediaJob).toHaveBeenCalledWith(
        expect.objectContaining({ status: 'pending', provider: 'luma', operation: 'video' }),
      );
    });

    it('stores the provider job reference under the pending:// scheme', async () => {
      const { service, aiSettings } = makeService();
      await service.attachProviderJob('job-1', 'ext-99', 'org-1');
      expect(aiSettings.updateMediaJob).toHaveBeenCalledWith('org-1', 'job-1', { artifactUrl: 'pending://ext-99' });
    });

    it('extracts the provider job ref only from pending:// values', () => {
      const { service } = makeService();
      expect(service.providerJobRef(makeJob({ artifactUrl: 'pending://abc' }))).toBe('abc');
      expect(service.providerJobRef(makeJob({ artifactUrl: 'https://real/url.mp4' }))).toBeNull();
      expect(service.providerJobRef(makeJob({ artifactUrl: null }))).toBeNull();
    });

    it('builds an org-bound webhook URL and omits it when no base URL is set', () => {
      const { service } = makeService();
      const url = service.webhookUrlFor('job-1', 'org-1');
      expect(url).toMatch(/^https:\/\/api\.example\.com\/media-jobs\/webhook\/job-1\/[0-9a-f]{64}$/);

      delete process.env.NEXT_PUBLIC_BACKEND_URL;
      expect(service.webhookUrlFor('job-1', 'org-1')).toBeUndefined();
    });

    it('omits the webhook for a non-HTTPS base (providers reject http/localhost)', () => {
      const { service } = makeService();
      const prev = process.env.NEXT_PUBLIC_BACKEND_URL;
      process.env.NEXT_PUBLIC_BACKEND_URL = 'http://localhost:3000';
      expect(service.webhookUrlFor('job-1', 'org-1')).toBeUndefined();
      process.env.NEXT_PUBLIC_BACKEND_URL = prev;
    });
  });

  describe('processJob', () => {
    it('skips unknown or already-finished jobs', async () => {
      const { service, jobs } = makeService();
      expect(await service.processJob('nope')).toBe('skipped');

      jobs.set('done-1', makeJob({ id: 'done-1', status: 'completed' }));
      expect(await service.processJob('done-1')).toBe('skipped');
    });

    it('fails jobs that exceeded the 24h timeout', async () => {
      const { service, jobs, aiSettings, notificationService } = makeService();
      jobs.set('old-1', makeJob({ id: 'old-1', createdAt: new Date(Date.now() - 25 * 60 * 60 * 1000) }));

      expect(await service.processJob('old-1')).toBe('failed');
      expect(aiSettings.updateMediaJob).toHaveBeenCalledWith(
        'org-1',
        'old-1',
        expect.objectContaining({ status: 'failed' }),
      );
      expect(notificationService.notify).toHaveBeenCalled();
    });

    it('stays pending while the provider is still working (and marks processing)', async () => {
      const { service, jobs, pollJob, aiSettings } = makeService();
      jobs.set('job-1', makeJob());
      pollJob.mockResolvedValue({ status: 'pending' });

      expect(await service.processJob('job-1')).toBe('pending');
      expect(pollJob).toHaveBeenCalledWith('luma-ext-1', { credentials: { apiKey: 'luma-key' } });
      // §3.1: the pending→processing write is now a guarded conditional claim.
      expect(aiSettings.claimMediaJobStatus).toHaveBeenCalledWith('org-1', 'job-1', ['pending'], 'processing');
    });

    it('polls through the version pinned on the job, not the config current version (4.10)', async () => {
      const { service, jobs, pollJob, resolution, orgSettings } = makeService();
      // job was created under v1; the org config has since been upgraded to v2.
      jobs.set('job-1', makeJob({ version: 'v1' }));
      orgSettings.getConfigForProvider.mockResolvedValue({
        credentials: { apiKey: 'luma-key' },
        storageProviderId: null,
        storageRootFolderId: null,
        version: 'v2',
      });
      pollJob.mockResolvedValue({ status: 'pending' });

      await service.processJob('job-1');

      expect(resolution.resolveMedia).toHaveBeenCalledWith(
        'luma',
        expect.objectContaining({ version: 'v1' }),
      );
    });

    it('a job created without a version stores v1 and polls through the v1 adapter (replicate community-model regression)', async () => {
      const { service, aiSettings, resolution, pollJob } = makeService();
      // Replicate community-model jobs carry a model VERSION HASH at dispatch
      // time; if that hash lands on the job row, resolveMedia looks up
      // media/replicate@<hash> and the job can never complete (prod job
      // cmvfpl5mr001xsyaew7n678pg).
      const job = await service.createPendingJob({
        organizationId: 'org-1',
        userId: 'user-1',
        provider: 'replicate',
        operation: 'video',
        model: 'arielreplicate/robust_video_matting',
      });
      expect(aiSettings.createMediaJob).toHaveBeenCalledWith(
        expect.objectContaining({ version: 'v1' }),
      );

      await service.attachProviderJob(job.id, 'pred-1', 'org-1');
      pollJob.mockResolvedValue({ status: 'pending' });

      await service.processJob(job.id);

      expect(resolution.resolveMedia).toHaveBeenCalledWith(
        'replicate',
        expect.objectContaining({ version: 'v1' }),
      );
    });

    it('treats transient poll errors as pending (retried next sweep)', async () => {
      const { service, jobs, pollJob } = makeService();
      jobs.set('job-1', makeJob());
      pollJob.mockRejectedValue(new Error('network blip'));

      expect(await service.processJob('job-1')).toBe('pending');
    });

    it('fails the job when the provider reports failure', async () => {
      const { service, jobs, pollJob, notificationService } = makeService();
      jobs.set('job-1', makeJob());
      pollJob.mockResolvedValue({ status: 'failed', error: 'NSFW rejected' });

      expect(await service.processJob('job-1')).toBe('failed');
      expect(jobs.get('job-1')!.status).toBe('failed');
      expect(jobs.get('job-1')!.error).toContain('NSFW rejected');
      expect(notificationService.notify).toHaveBeenCalledWith(
        expect.objectContaining({
          orgId: 'org-1',
          category: 'media',
          title: expect.stringContaining('failed'),
          message: expect.stringContaining('failed'),
          channels: { email: false, push: false, inApp: true },
        })
      );
    });

    it('stores the structured envelope (kind + settingsUrl) for a provider-attributed poll failure', async () => {
      // A poll-time quota failure must keep the 502-envelope information so the
      // render queue can link Settings — the bare string rendered verbatim
      // looked like a generic crash (B7).
      const { service, jobs, pollJob, notificationService } = makeService();
      jobs.set('job-1', makeJob());
      const attributed =
        "Replicate reports the account's quota or billing limit was reached (HTTP 402): insufficient credits";
      pollJob.mockResolvedValue({ status: 'failed', error: attributed });

      expect(await service.processJob('job-1')).toBe('failed');
      const stored = JSON.parse(jobs.get('job-1')!.error!);
      expect(stored).toEqual({
        message: attributed,
        kind: 'quota',
        settingsUrl: '/settings/content/ai-media',
      });
      // The notification keeps the PLAIN text, not the JSON envelope.
      expect(notificationService.notify).toHaveBeenCalledWith(
        expect.objectContaining({
          message: expect.stringContaining('quota or billing limit'),
        })
      );
      const notifyMessage = notificationService.notify.mock.calls[0][0].message as string;
      expect(notifyMessage.startsWith('{')).toBe(false);
    });

    it('downloads, stores under the typed folder, completes, and notifies on success', async () => {
      const { service, jobs, pollJob, orgSettings, storageAdapter, mediaRepository, notificationService, videoThumbnailService } =
        makeService();
      jobs.set('job-1', makeJob());
      orgSettings.getConfigForProvider.mockResolvedValue({
        credentials: { apiKey: 'luma-key' },
        storageProviderId: null,
        storageRootFolderId: 'root-1',
        version: 'v1',
      });
      pollJob.mockResolvedValue({
        status: 'completed',
        artifactUrl: 'https://provider.example.com/out.mp4',
        metadata: { durationSeconds: 5, model: 'dream-machine' },
      });
      mockSafeFetch.mockResolvedValue({
        ok: true,
        headers: new Headers({ 'content-type': 'video/mp4', 'content-length': '4' }),
        arrayBuffer: async () => new Uint8Array([1, 2, 3, 4]).buffer,
      });

      expect(await service.processJob('job-1')).toBe('completed');

      // artifact downloaded via safeFetch (provider URLs expire)
      expect(mockSafeFetch).toHaveBeenCalledWith('https://provider.example.com/out.mp4', undefined);
      // written into tenant storage
      expect(storageAdapter.writeBuffer).toHaveBeenCalledWith(expect.any(Buffer), 'video/mp4');
      // typed folder under the provider root (video operation → video/)
      expect(orgSettings.getStandardFolderId).toHaveBeenCalledWith('org-1', 'root-1', 'video');
      // Media row with extracted metadata
      expect(mediaRepository.saveGeneratedMedia).toHaveBeenCalledWith('org-1', expect.objectContaining({
        type: 'video',
        folderId: 'folder-video-1',
        fileSize: 4,
        metadata: expect.objectContaining({
          durationSeconds: 5,
          model: 'dream-machine',
          provider: 'luma',
          mime: 'video/mp4',
        }),
      }));
      // job completed with the stored (tenant) URL, not the provider URL
      expect(jobs.get('job-1')!.status).toBe('completed');
      expect(jobs.get('job-1')!.artifactUrl).toBe('/uploads/org-1/artifact.mp4');
      // user notified
      expect(notificationService.notify).toHaveBeenCalledWith(
        expect.objectContaining({
          orgId: 'org-1',
          category: 'media',
          title: expect.stringContaining('ready'),
          message: expect.stringContaining('ready'),
          channels: { email: false, push: false, inApp: true },
        })
      );
      // URL-landed video artifact → async thumbnail generation enqueued
      expect(videoThumbnailService.enqueueGenerate).toHaveBeenCalledWith('org-1', 'media-1');
    });

    it('does not enqueue a video thumbnail for non-video operations', async () => {
      const { service, jobs, pollJob, videoThumbnailService } = makeService();
      jobs.set('job-1', makeJob({ operation: 'image' }));
      pollJob.mockResolvedValue({
        status: 'completed',
        artifactUrl: 'https://provider.example.com/out.png',
        metadata: {},
      });
      mockSafeFetch.mockResolvedValue({
        ok: true,
        headers: new Headers({ 'content-type': 'image/png', 'content-length': '4' }),
        arrayBuffer: async () => new Uint8Array([1, 2, 3, 4]).buffer,
      });

      expect(await service.processJob('job-1')).toBe('completed');
      expect(videoThumbnailService.enqueueGenerate).not.toHaveBeenCalled();
    });

    it('stores actual JPEG slide bytes as an image and skips video thumbnail generation', async () => {
      const { service, jobs, pollJob, orgSettings, storageAdapter, mediaRepository, videoThumbnailService } = makeService();
      jobs.set('job-1', makeJob({ operation: 'slide' }));
      orgSettings.getConfigForProvider.mockResolvedValue({
        credentials: { apiKey: 'k' },
        storageProviderId: null,
        storageRootFolderId: 'root-1',
        version: 'v1',
      });
      pollJob.mockResolvedValue({
        status: 'completed',
        artifactUrl: 'https://provider.example.com/slide',
      });
      mockSafeFetch.mockResolvedValue({
        ok: true,
        headers: new Headers({ 'content-type': 'video/mp4' }),
        arrayBuffer: async () => tinyJpeg.buffer.slice(
          tinyJpeg.byteOffset,
          tinyJpeg.byteOffset + tinyJpeg.byteLength,
        ),
      });

      expect(await service.processJob('job-1')).toBe('completed');

      expect(storageAdapter.writeBuffer).toHaveBeenCalledWith(tinyJpeg, 'image/jpeg');
      expect(orgSettings.getStandardFolderId).toHaveBeenCalledWith('org-1', 'root-1', 'images');
      expect(mediaRepository.saveGeneratedMedia).toHaveBeenCalledWith('org-1', expect.objectContaining({
        name: 'slide-job-1.jpg',
        type: 'image',
        metadata: expect.objectContaining({ mime: 'image/jpeg' }),
      }));
      expect(videoThumbnailService.enqueueGenerate).not.toHaveBeenCalled();
    });

    it.each([
      ['image/gif', Buffer.from('GIF89a'), 'gif'],
      ['image/webp', Buffer.concat([Buffer.from('RIFF'), Buffer.from([4, 0, 0, 0]), Buffer.from('WEBP')]), 'webp'],
    ])('preserves the slide operation category for %s', async (mime, bytes, ext) => {
      const { service, jobs, pollJob, mediaRepository, videoThumbnailService } = makeService();
      jobs.set('job-1', makeJob({ operation: 'slide' }));
      pollJob.mockResolvedValue({
        status: 'completed',
        artifactUrl: `data:${mime};base64,${bytes.toString('base64')}`,
      });

      expect(await service.processJob('job-1')).toBe('completed');

      expect(mediaRepository.saveGeneratedMedia).toHaveBeenCalledWith('org-1', expect.objectContaining({
        name: `slide-job-1.${ext}`,
        type: 'video',
        metadata: expect.objectContaining({ mime }),
      }));
      expect(videoThumbnailService.enqueueGenerate).toHaveBeenCalledWith('org-1', 'media-1');
    });

    it('detects a normal MP4 from bytes when the response MIME is octet-stream', async () => {
      const { service, jobs, pollJob, storageAdapter, mediaRepository, videoThumbnailService } = makeService();
      jobs.set('job-1', makeJob());
      pollJob.mockResolvedValue({
        status: 'completed',
        artifactUrl: `data:application/octet-stream;base64,${tinyMp4.toString('base64')}`,
      });

      expect(await service.processJob('job-1')).toBe('completed');

      expect(storageAdapter.writeBuffer).toHaveBeenCalledWith(tinyMp4, 'video/mp4');
      expect(mediaRepository.saveGeneratedMedia).toHaveBeenCalledWith('org-1', expect.objectContaining({
        name: 'video-job-1.mp4',
