import { Injectable, Logger } from '@nestjs/common';
import { OrgMediaProviderSettingsRepository } from '@postmill-ai/nestjs-libraries/database/prisma/media-providers/org-media-provider-settings.repository';
import { OrgAiSettingsRepository } from '@postmill-ai/nestjs-libraries/database/prisma/ai-settings/org-ai-settings.repository';
import { EncryptionService } from '@postmill-ai/nestjs-libraries/encryption/encryption.service';
import { ProviderResolutionService } from '@postmill-ai/nestjs-libraries/providers/provider-resolution.service';

// §11.4 auto-config live-link: OpenAI and MiniMax are both AI providers and media
// providers and share one API key. Configuring (or re-keying) either surface updates
// both rows — single credential source. The media row keeps its own storage binding
// (the upsert only touches credentials/enabled). Depends only on the two repositories,
// so the AI- and media-settings services can both inject it without a DI cycle.
const LINKED_PROVIDERS = new Set(['openai', 'minimax']);

// Intentional cross-domain credential-link service: mirrors API keys between the
// AI-settings and media-providers domains for providers that are both an LLM hub and
// a media generation surface. It lives in the media-providers folder because its
// primary consumer is OrgMediaProviderSettingsService, but it writes both AI and media
// config rows. No DI cycle is introduced — both owning services depend on this leaf.
@Injectable()
export class ProviderCredentialLinkService {
  private readonly _logger = new Logger(ProviderCredentialLinkService.name);

  constructor(
    private _mediaRepository: OrgMediaProviderSettingsRepository,
    private _aiRepository: OrgAiSettingsRepository,
    private _encryption: EncryptionService,
    private _resolution: ProviderResolutionService,
  ) {}

  isLinked(identifier: string): boolean {
    return LINKED_PROVIDERS.has(identifier);
  }

  // 1.4/1.2: resolve the pinned version for the mirror-target row the same way the
  // owning settings services do — the target row's stored version, else the latest
  // active version, else v1. Hardcoding v1 would split rows (mirror at v1, primary
  // at v2) the moment a linked provider ships v2. Computed from an already-fetched
  // row (a version-AGNOSTIC read — findUnique-by-v1 would miss a v2-pinned row).
  private _pinnedVersion(
    domain: 'ai' | 'media',
    identifier: string,
    existing: { version?: string | null } | null,
  ): string {
    return (
      existing?.version ??
      this._resolution.latestActiveVersion(domain, identifier) ??
      'v1'
    );
  }

  // AI provider configured/re-keyed → mirror credentials onto the media config.
  async syncFromAiProvider(
    orgId: string,
    identifier: string,
    credentials: Record<string, string>,
  ): Promise<void> {
    if (!this.isLinked(identifier)) return;
    try {
      const existing = await this._mediaRepository.findAnyByIdentifier(
        orgId,
        identifier,
      );
      const version = this._pinnedVersion('media', identifier, existing);
      await this._mediaRepository.upsert(
        orgId,
        identifier,
        {
          // 1.1(c): preserve the existing mirror row's enabled flag — a re-key must
          // not silently re-enable a deliberately-disabled provider. Default to
          // enabled:true only when creating a brand-new mirror row.
          enabled: existing ? existing.enabled : true,
          credentials: this._encryption.encrypt(JSON.stringify(credentials)),
        },
        version,
      );
    } catch (err) {
      // Non-fatal: the primary surface's save must not fail because of the mirror.
      this._logger.warn(
        `Failed to mirror AI credentials to media config for ${identifier}: ${(err as Error).message}`,
      );
    }
  }

  // Media provider configured/re-keyed → mirror credentials onto the AI config.
  async syncFromMediaProvider(
    orgId: string,
    identifier: string,
    credentials: Record<string, string>,
  ): Promise<void> {
    if (!this.isLinked(identifier)) return;
    try {
      const existing = await this._aiRepository.findAnyByIdentifier(
        orgId,
        identifier,
      );
      const version = this._pinnedVersion('ai', identifier, existing);
      await this._aiRepository.upsert(
        orgId,
        identifier,
        {
          // 1.1(c): preserve a disabled mirror row's state on re-key (create → true).
          enabled: existing ? existing.enabled : true,
          credentials: this._encryption.encrypt(JSON.stringify(credentials)),
        },
        version,
      );
    } catch (err) {
      this._logger.warn(
        `Failed to mirror media credentials to AI config for ${identifier}: ${(err as Error).message}`,
      );
    }
  }
}

import 'reflect-metadata';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { BadRequestException, HttpException } from '@nestjs/common';

// ioRedis is touched by _bustDefaultsCatalogCache on the success path — stub it so no
// real connection is attempted.
vi.mock('@postmill-ai/nestjs-libraries/redis/redis.service', () => ({
  ioRedis: {
    keys: vi.fn().mockResolvedValue([]),
    del: vi.fn().mockResolvedValue(0),
  },
}));

import { MediaProviderController } from './media-provider.controller';

const org = { id: 'org-1' } as any;

function makeController(overrides: {
  configs?: any[];
  getFolder?: any;
} = {}) {
  const orgMedia = { upsert: vi.fn().mockResolvedValue({}) };
  const storageService = {
    getProviderConfigs: vi
      .fn()
      .mockResolvedValue(overrides.configs ?? [{ id: 'store-1', organizationId: 'org-1' }]),
  };
  const fileService = {
    getFolder:
      overrides.getFolder ?? vi.fn().mockResolvedValue({ id: 'folder-1', organizationId: 'org-1' }),
  };
  const orgMediaProviderSettings = {
    setStorage: vi.fn(async (orgId: string, identifier: string, data: any) => {
      const configs = await storageService.getProviderConfigs(orgId);
      if (!configs.some((c: any) => c.id === data.storageProviderId)) {
        throw new BadRequestException(
          'storageProviderId does not belong to this organization',
        );
      }
      if (data.storageRootFolderId) {
        try {
          await fileService.getFolder(orgId, data.storageRootFolderId);
        } catch (err) {
          if (!(err instanceof HttpException) || err.getStatus() !== 404) throw err;
          throw new BadRequestException(
            'storageRootFolderId does not belong to this organization',
          );
        }
      }
      await orgMedia.upsert(orgId, identifier, data);
      return { identifier, success: true };
    }),
  };
  const controller = new MediaProviderController(orgMediaProviderSettings as any);
  return { controller, orgMedia, storageService, fileService, orgMediaProviderSettings };
}

// PROVIDER_REMEDIATION 3.6: validate storageProviderId + storageRootFolderId belong to
// the caller's org at WRITE time (not deferred to job completion after a paid render).
describe('MediaProviderController.setStorage ownership (3.6)', () => {
  beforeEach(() => vi.clearAllMocks());

  it('persists when both ids belong to the org', async () => {
    const { controller, orgMedia } = makeController({
      configs: [{ id: 'store-1', organizationId: 'org-1' }],
    });

    const result = await controller.setStorage(org, 'openai', {
      storageProviderId: 'store-1',
      storageRootFolderId: 'folder-1',
    });

    expect(result).toEqual({ identifier: 'openai', success: true });
    expect(orgMedia.upsert).toHaveBeenCalledWith('org-1', 'openai', {
      storageProviderId: 'store-1',
      storageRootFolderId: 'folder-1',
    });
  });

  it('rejects a storageProviderId owned by another org', async () => {
    const { controller, orgMedia } = makeController({
      configs: [{ id: 'store-1', organizationId: 'org-1' }],
    });

    await expect(
      controller.setStorage(org, 'openai', { storageProviderId: 'store-OTHER' }),
    ).rejects.toThrow(BadRequestException);
    expect(orgMedia.upsert).not.toHaveBeenCalled();
  });

  it('rejects a storageRootFolderId owned by another org', async () => {
    const { controller, orgMedia } = makeController({
      configs: [{ id: 'store-1', organizationId: 'org-1' }],
      // getFolder throws HttpException(404) for a cross-org/missing folder — the
      // real FileService.getFolder shape. 3.4 now rethrows any NON-404 error, so
      // the mock must be the genuine 404 to still map to the ownership 400.
      getFolder: vi
        .fn()
        .mockRejectedValue(new HttpException('Folder not found', 404)),
    });

    await expect(
      controller.setStorage(org, 'openai', {
        storageProviderId: 'store-1',
        storageRootFolderId: 'folder-OTHER',
      }),
    ).rejects.toThrow(BadRequestException);
    expect(orgMedia.upsert).not.toHaveBeenCalled();
  });

  // 3.4: an infra failure (DB outage, transient Prisma error) must PROPAGATE —
  // not be swallowed into a 400 "does not belong to this organization" that
  // blames the user's input for a server-side blip.
  it('rethrows a non-404 getFolder failure instead of mapping it to the ownership 400', async () => {
    const infraError = new Error('db connection lost');
    const { controller, orgMedia } = makeController({
      configs: [{ id: 'store-1', organizationId: 'org-1' }],
      getFolder: vi.fn().mockRejectedValue(infraError),
    });

    await expect(
      controller.setStorage(org, 'openai', {
        storageProviderId: 'store-1',
        storageRootFolderId: 'folder-1',
      }),
    ).rejects.toBe(infraError);
    expect(orgMedia.upsert).not.toHaveBeenCalled();
  });

  it('accepts the synthetic __virtual_local__ provider id', async () => {
    const { controller, orgMedia } = makeController({
      configs: [{ id: '__virtual_local__', organizationId: 'org-1' }],
    });

    await controller.setStorage(org, 'openai', { storageProviderId: '__virtual_local__' });
    expect(orgMedia.upsert).toHaveBeenCalled();
  });
});

