import { MediaQueue, MediaQueuePanel } from './media-queue';

const job = (id: string, status = 'completed') => ({
  id,
  provider: 'heygen',
  operation: 'video',
  status,
  artifactUrl: '/uploads/a.mp4',
  fileId: 'file-1',
  error: null,
  createdAt: '2026-07-01T00:00:00.000Z',
});

const counts = { pending: 2, processing: 1, failed7d: 3 };

beforeEach(() => {
  mockReplace.mockClear();
  searchParams = new URLSearchParams();
  requestedStatus = undefined;
  queueState = {
    jobs: [job('job-1'), job('job-2')],
    counts,
    error: undefined,
    isLoading: false,
    hasMore: false,
    isLoadingMore: false,
    loadMore: vi.fn(),
  };
  widgetState = { data: { jobs: [job('job-1')], counts }, isLoading: false };
});
afterEach(cleanup);

describe('MediaQueue', () => {
  it('shows the unfiltered counts and the jobs', () => {
    render(<MediaQueue />);

    expect(screen.getByText('2')).toBeTruthy();
    expect(screen.getByText('1')).toBeTruthy();
    expect(screen.getByText('3')).toBeTruthy();
    expect(screen.getAllByTestId('queue-job').length).toBe(2);
  });

  it('requests the status from the URL, not from local state', () => {
    searchParams = new URLSearchParams('status=failed');
    render(<MediaQueue />);

    expect(requestedStatus).toBe('failed');
    expect(screen.getByRole('button', { name: 'Failed' }).getAttribute('aria-pressed')).toBe(
      'true'
    );
  });

  it('ignores a status the backend would reject', () => {
    searchParams = new URLSearchParams('status=bogus');
    render(<MediaQueue />);

    expect(requestedStatus).toBeUndefined();
    expect(screen.getByRole('button', { name: 'All' }).getAttribute('aria-pressed')).toBe('true');
  });

  it('puts the chosen filter in the URL and drops a stale job highlight', () => {
    searchParams = new URLSearchParams('job=job-9');
    render(<MediaQueue />);

    fireEvent.click(screen.getByRole('button', { name: 'Failed' }));

    expect(mockReplace).toHaveBeenCalledWith('/media/queue?status=failed', { scroll: false });
  });

  it('clearing the filter leaves no query string behind', () => {
    searchParams = new URLSearchParams('status=failed');
    render(<MediaQueue />);

    fireEvent.click(screen.getByRole('button', { name: 'All' }));

    expect(mockReplace).toHaveBeenCalledWith('/media/queue', { scroll: false });
  });

  it('passes ?job= through so that row is highlighted', () => {
    searchParams = new URLSearchParams('job=job-2');
    render(<MediaQueue />);

    expect(screen.getByTestId('render-queue').getAttribute('data-highlight')).toBe('job-2');
  });

  it('offers a studio when nothing has ever rendered, but not when a filter is empty', () => {
    queueState = { ...queueState, jobs: [] };
    const { unmount } = render(<MediaQueue />);
    expect(screen.getByText('No renders yet')).toBeTruthy();
    expect(screen.getByRole('link', { name: 'Open a studio' })).toBeTruthy();
    unmount();

    searchParams = new URLSearchParams('status=failed');
    render(<MediaQueue />);
    expect(screen.getByText('Nothing with that status')).toBeTruthy();
    expect(screen.queryByRole('link', { name: 'Open a studio' })).toBeNull();
  });

  it('keeps the loaded pages when the next one fails', () => {
    // SWR-infinite sets `error` for the whole list; blanking the screen because
    // page 2 failed loses page 1 for no reason.
    queueState = { ...queueState, error: new Error('500') };
    render(<MediaQueue />);

    expect(screen.getAllByTestId('queue-job').length).toBe(2);
    expect(screen.queryByText('Could not load the queue')).toBeTruthy();
    expect(screen.getByRole('button', { name: 'Retry' })).toBeTruthy();
  });

  it('shows the error block only when there is nothing on screen', () => {
    queueState = { ...queueState, jobs: [], error: new Error('500') };
    render(<MediaQueue />);

    expect(screen.getByText('Could not load the queue')).toBeTruthy();
    expect(screen.queryByTestId('queue-job')).toBeNull();
  });

  it('pages only while there is more to load', () => {
    render(<MediaQueue />);
    expect(screen.queryByRole('button', { name: 'Load more' })).toBeNull();
    cleanup();

    queueState = { ...queueState, hasMore: true };
    render(<MediaQueue />);
    fireEvent.click(screen.getByRole('button', { name: 'Load more' }));
    expect(queueState.loadMore).toHaveBeenCalled();
  });
});

describe('MediaQueuePanel', () => {
  it('links to the full queue and counts what is running', () => {
    render(<MediaQueuePanel />);

    expect(screen.getByRole('link', { name: 'View all' }).getAttribute('href')).toBe(
      '/media/queue'
    );
    expect(screen.getByText('3 running')).toBeTruthy();
  });

  it('renders nothing on an org that has never generated anything', () => {
    widgetState = { data: { jobs: [], counts: { pending: 0, processing: 0, failed7d: 0 } }, isLoading: false };
    const { container } = render(<MediaQueuePanel />);

    expect(container.firstChild).toBeNull();
  });
});

import 'reflect-metadata';
import { describe, it, expect, vi } from 'vitest';
import { ListMediaProvidersTool } from './media.providers.tool';
import { executeTool, makeOrganization, makeUser } from './__tests__/tool-test.harness';

describe('ListMediaProvidersTool', () => {
  const org = makeOrganization();
  const user = makeUser();

  const noDefaults = {
    getMediaDefaults: vi.fn().mockResolvedValue({ categories: [] }),
  };

  it('returns configured and enabled providers', async () => {
    const service = {
      getProviders: vi.fn().mockResolvedValue([
        {
          identifier: 'runway',
          name: 'Runway',
          capabilities: { video: true },
          enabled: true,
          isConfigured: true,
        },
        {
          identifier: 'luma',
          name: 'Luma',
          capabilities: { video: true },
          enabled: true,
          isConfigured: false,
        },
        {
          identifier: 'openai',
          name: 'OpenAI',
          capabilities: { image: true, audio: true },
          enabled: false,
          isConfigured: true,
        },
      ]),
    };
    const tool = new ListMediaProvidersTool(service as any, noDefaults as any);

    const result = await executeTool(tool, {
      inputData: {},
      organization: org,
      user,
      access: { mode: 'user' },
    });

    expect(Array.isArray(result)).toBe(true);
    expect(result).toHaveLength(1);
    expect(result[0]).toEqual({
      identifier: 'runway',
      name: 'Runway',
      capabilities: { video: true },
      defaults: [],
    });
  });

  it('attaches the org defaults for the provider and survives a defaults-service failure', async () => {
    const service = {
      getProviders: vi.fn().mockResolvedValue([
        {
          identifier: 'openrouter',
          name: 'OpenRouter',
          capabilities: { image: true },
          enabled: true,
          isConfigured: true,
        },
      ]),
    };
    const defaults = {
      getMediaDefaults: vi.fn().mockResolvedValue({
        categories: [
          { category: 'text-to-image', providerId: 'openrouter', model: 'google/gemini-2.5-flash-image' },
          { category: 'image-to-image', providerId: 'openrouter', model: 'google/gemini-2.5-flash-image' },
          { category: 'text-to-video', providerId: 'runway', model: 'gen4' },
          { category: 'text-to-speech', source: null },
        ],
      }),
    };
    const tool = new ListMediaProvidersTool(service as any, defaults as any);

    const result = await executeTool(tool, {
      inputData: {},
      organization: org,
      user,
      access: { mode: 'user' },
    });

    expect(result[0].defaults).toEqual([
      { category: 'text-to-image', model: 'google/gemini-2.5-flash-image' },
      { category: 'image-to-image', model: 'google/gemini-2.5-flash-image' },
    ]);

    const failing = { getMediaDefaults: vi.fn().mockRejectedValue(new Error('redis down')) };
    const tool2 = new ListMediaProvidersTool(service as any, failing as any);
    const result2 = await executeTool(tool2, {
      inputData: {},
      organization: org,
      user,
      access: { mode: 'user' },
    });
    expect(result2[0].defaults).toEqual([]);
  });

  it('denies read without access context', async () => {
    const tool = new ListMediaProvidersTool({ getProviders: vi.fn() } as any, noDefaults as any);

    await expect(
      executeTool(tool, { inputData: {}, organization: org, user })
    ).rejects.toThrow('Read access denied: no access context');
  });

  it('denies mcp read without mcp:read scope', async () => {
    const tool = new ListMediaProvidersTool({ getProviders: vi.fn() } as any, noDefaults as any);

    await expect(
      executeTool(tool, {
        inputData: {},
        organization: org,
        user,
        access: { mode: 'mcp', scopes: [] },
      })
    ).rejects.toThrow('Read access denied: mcp:read scope required');
  });
});

import 'reflect-metadata';
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';

import { AuthProviderManager } from './auth-provider.manager';

const ORIGINAL_ENV = { ...process.env };

// Every env var the getProviders env fallback can key on. Fallback tests must
// start from a clean slate so developer-machine / CI env cannot leak providers
// into the advertised list.
const PROVIDER_ENV_VARS = [
  'IS_GENERAL',
  'POSTMILL_GENERIC_OAUTH',
  'POSTMILL_OAUTH_CLIENT_ID',
  'POSTMILL_OAUTH_CLIENT_SECRET',
  'POSTMILL_OAUTH_AUTH_URL',
  'POSTMILL_OAUTH_TOKEN_URL',
  'POSTMILL_OAUTH_USERINFO_URL',
  'NEXT_PUBLIC_POSTMILL_OAUTH_DISPLAY_NAME',
  'YOUTUBE_CLIENT_ID',
  'YOUTUBE_CLIENT_SECRET',
  'GITHUB_CLIENT_ID',
  'GITHUB_CLIENT_SECRET',
  'NEYNAR_CLIENT_ID',
  'STRIPE_PUBLISHABLE_KEY',
  'FACEBOOK_SSO_ENABLED',
  'FACEBOOK_APP_ID',
  'FACEBOOK_APP_SECRET',
  'X_SSO_ENABLED',
  'X_API_KEY',
  'X_API_SECRET',
  'X_CLIENT_ID',
  'X_CLIENT_SECRET',
  'LINKEDIN_SSO_ENABLED',
  'LINKEDIN_CLIENT_ID',
  'LINKEDIN_CLIENT_SECRET',
  'APPLE_SSO_ENABLED',
  'APPLE_CLIENT_ID',
  'APPLE_TEAM_ID',
  'APPLE_KEY_ID',
  'APPLE_PRIVATE_KEY',
];

function clearProviderEnv() {
  for (const key of PROVIDER_ENV_VARS) {
    delete process.env[key];
  }
}

function setGenericOauthEnv() {
  process.env.POSTMILL_OAUTH_CLIENT_ID = 'oidc-id';
  process.env.POSTMILL_OAUTH_CLIENT_SECRET = 'oidc-secret';
  process.env.POSTMILL_OAUTH_AUTH_URL = 'https://idp.example.com/authorize';
  process.env.POSTMILL_OAUTH_TOKEN_URL = 'https://idp.example.com/token';
  process.env.POSTMILL_OAUTH_USERINFO_URL = 'https://idp.example.com/userinfo';
}

function makeManager(overrides: {
  kernel?: Partial<{
    latestActive: (...args: any[]) => any;
    versions: (...args: any[]) => any;
    resolveForRead: (...args: any[]) => any;
  }>;
  repo?: Partial<{ list: (...args: any[]) => any }>;
  runtimeContext?: Partial<{ build: (...args: any[]) => any }>;
}) {
  const kernel = {
    latestActive: vi.fn().mockReturnValue(undefined),
    versions: vi.fn().mockReturnValue([]),
    resolveForRead: vi.fn().mockReturnValue({
      create: vi.fn().mockReturnValue({ mocked: 'provider' }),
    }),
    ...overrides.kernel,
  };

  const repo = {
    list: vi.fn().mockResolvedValue([]),
    ...overrides.repo,
  };

  const runtimeContext = {
    build: vi.fn().mockReturnValue({ mocked: 'ctx' }),
    ...overrides.runtimeContext,
  };

  const manager = new AuthProviderManager(
    kernel as any,
    runtimeContext as any,
    repo as any
  );

  return { manager, kernel, repo, runtimeContext };
}

beforeEach(() => {
  vi.clearAllMocks();
});

afterEach(() => {
  process.env = { ...ORIGINAL_ENV };
});

describe('AuthProviderManager', () => {
  describe('getProviders', () => {
    it('overlays enabled DB providers onto the env list (LOCAL always present)', async () => {
      clearProviderEnv();
      const { manager, kernel, repo } = makeManager({
        repo: {
          list: vi.fn().mockResolvedValue([
            {
              provider: 'GOOGLE',
              enabled: true,
              displayName: 'Workspace SSO',
            },
            { provider: 'GITHUB', enabled: false, displayName: null },
            { provider: 'GENERIC', enabled: true, displayName: null },
          ]),
        },
        kernel: {
          latestActive: vi.fn().mockReturnValue({
            manifest: { version: 'v2', status: 'active' },
          }),
        },
      });

      const result = await manager.getProviders();

      expect(repo.list).toHaveBeenCalled();
      expect(result.providers).toEqual([
        { provider: 'LOCAL', displayName: 'Email', version: 'v2', status: 'active' },
        { provider: 'GOOGLE', displayName: 'Workspace SSO', version: 'v2', status: 'active' },
        { provider: 'GENERIC', displayName: 'OIDC', version: 'v2', status: 'active' },
      ]);
    });

    it('merges DB rows with env providers: DB wins per provider, env-only providers stay listed', async () => {
      clearProviderEnv();
      process.env.YOUTUBE_CLIENT_ID = 'yt-id';
      process.env.YOUTUBE_CLIENT_SECRET = 'yt-secret';
      process.env.FACEBOOK_SSO_ENABLED = 'true';
      process.env.FACEBOOK_APP_ID = 'fb-app-id';
      process.env.FACEBOOK_APP_SECRET = '[REDACTED]';
      const { manager } = makeManager({
        repo: {
          list: vi.fn().mockResolvedValue([
            {
              provider: 'GOOGLE',
              enabled: true,
              displayName: 'Workspace SSO',
            },
            { provider: 'X', enabled: true, displayName: null },
          ]),
        },
      });

      const result = await manager.getProviders();

      expect(result.providers).toEqual([
        { provider: 'LOCAL', displayName: 'Email', version: 'v1', status: 'active' },
        // DB row wins over the env-derived GOOGLE entry (DB displayName preferred)
        { provider: 'GOOGLE', displayName: 'Workspace SSO', version: 'v1', status: 'active' },
        // env-only provider stays listed
        { provider: 'FACEBOOK', displayName: 'Facebook', version: 'v1', status: 'active' },
        // DB-only provider is appended
        { provider: 'X', displayName: 'X', version: 'v1', status: 'active' },
      ]);
    });

    it('falls back to LOCAL only when no DB config and no platform env credentials exist', async () => {
      clearProviderEnv();
      const { manager } = makeManager({});

      const result = await manager.getProviders();

      expect(result.providers).toEqual([
        { provider: 'LOCAL', displayName: 'Email', version: 'v1', status: 'active' },
      ]);
    });

